#include "fastcsv.h"

int fastcsv_count_fields(const char *line) {
    if (line == 0 || *line == '\0') {
        return 0;
    }
    int fields = 1;
    for (const char *p = line; *p != '\0'; ++p) {
        if (*p == ',') {
            ++fields;
        }
    }
    return fields;
}

#ifndef FASTCSV_H
#define FASTCSV_H

/* fastcsv — a tiny CSV record helper. */
#define FASTCSV_VERSION "1.4.0"

/* Count the comma-separated fields in one CSV record (no quote handling). */
int fastcsv_count_fields(const char *line);

#endif /* FASTCSV_H */
